"""
    Converts seconds into hours, minutes and seconds
    :param sec: Seconds as a int
    :return: A good formatted time string
    """
def time_convert(sec: Any) -> object {
    mins = sec // 60;
    sec = sec % 60;
    hours = mins // 60;
    mins = mins % 60;
    return "{0}:{1}:{2}".format(int(hours), int(mins), sec);
}

